class ModelEvaluator:
    def __init__(self, model_name: str, memory_mb: float, tokens_per_sec: float):
        self.model_name = model_name
        self.memory_mb = memory_mb
        self.tokens_per_sec = tokens_per_sec
        self.test_cases = []

    def add_test_case(self, prompt: str, expected_keywords: list):
        self.test_cases.append({"prompt": prompt, "expected_keywords": expected_keywords})

    def _mock_generate(self, prompt: str) -> str:
        p = prompt.lower()
        if "python" in p:
            return "Python is an interpreted language with lists and dicts"
        if "math" in p or "add" in p:
            return "The answer is 4"
        return "I can help with that question"

    def run_tests(self) -> float:
        if not self.test_cases:
            return 0.0
        passed = 0
        for case in self.test_cases:
            response = self._mock_generate(case["prompt"]).lower()
            if any(str(k).lower() in response for k in case["expected_keywords"]):
                passed += 1
        return passed / len(self.test_cases)

    def deployment_report(self, max_memory=2000, min_speed=5, min_accuracy=0.7) -> dict:
        accuracy = self.run_tests()
        memory_ok = self.memory_mb <= max_memory
        speed_ok = self.tokens_per_sec >= min_speed
        accuracy_ok = accuracy >= min_accuracy
        return {
            "memory_ok": memory_ok,
            "speed_ok": speed_ok,
            "accuracy_ok": accuracy_ok,
            "ready": memory_ok and speed_ok and accuracy_ok,
        }


ev = ModelEvaluator("Qwen3-0.6B", memory_mb=1200, tokens_per_sec=12.0)
ev.add_test_case("Tell me about Python", ["interpreted", "language"])
ev.add_test_case("What is 2 + 2?", ["4"])
ev.add_test_case("Explain quantum physics", ["quantum"])
acc = ev.run_tests()
print(f"{acc:.2f}")
report = ev.deployment_report(max_memory=2000, min_speed=10, min_accuracy=0.6)
print(report["ready"])
